pub fn characterRigReleaseSkin() void {
    if (z3d.g_character_rig.skin_vertices) |vertices| std.heap.c_allocator.free(vertices);
    z3d.g_character_rig.skin_vertices = null;
    z3d.g_character_rig.skin_vertex_count = 0;
    z3d.g_character_rig.has_skin = false;
    z3d.g_character_rig.geometry_fingerprint = 0;
    z3d.g_character_rig.skin_key_len = 0;
}

pub fn characterRigClearViewport() void {
    z3d.characterRigReleaseSkin();
    z3d.g_character_rig = .{};
    z3d.g_character_rig_gizmo = .{};
}

pub fn characterRigGeometryFingerprint(state: *const character_rig_session.RigViewportState) u64 {
    var hasher = std.hash.Wyhash.init(0x52494731);
    hasher.update(std.mem.sliceAsBytes(state.snapshot.verts));
    if (state.snapshot.render_corner_logical_ids) |logical_ids| hasher.update(std.mem.sliceAsBytes(logical_ids));
    if (state.logical_weights) |weights| hasher.update(std.mem.sliceAsBytes(weights));
    return hasher.final();
}

pub fn characterRigBuildSkin(state: *const character_rig_session.RigViewportState, fingerprint: u64) bool {
    const weights = state.logical_weights orelse {
        z3d.characterRigReleaseSkin();
        return true;
    };
    const logical_ids = state.snapshot.render_corner_logical_ids orelse {
        z3d.characterRigReleaseSkin();
        return false;
    };
    const corner_count = logical_ids.len;
    if (corner_count == 0 or state.snapshot.verts.len != corner_count * 8 or
        weights.len != state.snapshot.logical_vertex_count)
    {
        z3d.characterRigReleaseSkin();
        return false;
    }
    if (z3d.g_character_rig.geometry_fingerprint == fingerprint and z3d.g_character_rig.skin_vertices != null) {
        z3d.g_character_rig.has_skin = true;
        return true;
    }
    const vertices = std.heap.c_allocator.alloc(f32, corner_count * 16) catch return false;
    for (logical_ids, 0..) |logical_id, corner| {
        if (logical_id >= weights.len) {
            std.heap.c_allocator.free(vertices);
            return false;
        }
        const source_at = corner * 8;
        const target_at = corner * 16;
        @memcpy(vertices[target_at .. target_at + 8], state.snapshot.verts[source_at .. source_at + 8]);
        const row = weights[logical_id];
        const packed_weights = character_skin_binding.quantizeWeights(row.weights) catch {
            std.heap.c_allocator.free(vertices);
            return false;
        };
        for (0..4) |influence| {
            const bone_index = row.bone_indices[influence];
            vertices[target_at + 8 + influence] = @floatFromInt(if (bone_index == character_skin_binding.UNUSED_BONE) 0 else bone_index);
            vertices[target_at + 12 + influence] = @as(f32, @floatFromInt(packed_weights[influence])) / 255.0;
        }
    }
    z3d.characterRigReleaseSkin();
    z3d.g_character_rig.skin_vertices = vertices;
    z3d.g_character_rig.skin_vertex_count = @intCast(corner_count);
    z3d.g_character_rig.geometry_fingerprint = fingerprint;
    const key = std.fmt.bufPrint(&z3d.g_character_rig.skin_key, "character-rig:{x}", .{fingerprint}) catch return false;
    z3d.g_character_rig.skin_key_len = @intCast(key.len);
    z3d.g_character_rig.has_skin = true;
    return true;
}

pub fn characterRigFrameSpecimens(state: *const character_rig_session.RigViewportState) void {
    if (state.snapshot.verts.len < 8) return;
    var minimum: [3]f32 = @splat(std.math.inf(f32));
    var maximum: [3]f32 = @splat(-std.math.inf(f32));
    var corner: usize = 0;
    while (corner < state.snapshot.verts.len / 8) : (corner += 1) {
        const at = corner * 8;
        for (0..3) |axis| {
            const value = state.snapshot.verts[at + axis];
            if (!std.math.isFinite(value)) continue;
            minimum[axis] = @min(minimum[axis], value);
            maximum[axis] = @max(maximum[axis], value);
        }
    }
    for (0..3) |axis| {
        if (!std.math.isFinite(minimum[axis]) or !std.math.isFinite(maximum[axis])) return;
    }
    const source_width = @max(0.001, maximum[0] - minimum[0]);
    z3d.g_character_rig.axis_length = @max(0.025, source_width * 0.075);
    const union_min = minimum;
    var union_max = maximum;
    union_max[0] += state.specimen_separation;
    const center = [3]f32{
        (union_min[0] + union_max[0]) * 0.5,
        (union_min[1] + union_max[1]) * 0.5,
        (union_min[2] + union_max[2]) * 0.5,
    };
    const half = [3]f32{
        (union_max[0] - union_min[0]) * 0.5,
        (union_max[1] - union_min[1]) * 0.5,
        (union_max[2] - union_min[2]) * 0.5,
    };
    const radius = @sqrt(half[0] * half[0] + half[1] * half[1] + half[2] * half[2]);
    z3d.orbitFrame(center, @max(radius * 1.08, source_width));
}

pub fn characterRigSyncViewport(state: *const character_rig_session.RigViewportState) void {
    if (state.bones.len == 0 or state.bones.len > z3d.CHARACTER_RIG_BONE_CAP or
        state.bind_global.len != state.bones.len or
        state.pose_global.len != state.bones.len or
        state.skin_matrices.len != state.bones.len)
    {
        z3d.characterRigClearViewport();
        return;
    }
    const source_hash = z3d.hashKey(state.source_key);
    const entering = !z3d.g_character_rig.active or z3d.g_character_rig.source_hash != source_hash;
    if (entering) z3d.characterRigFrameSpecimens(state);
    z3d.g_character_rig.active = true;
    z3d.g_character_rig.source_hash = source_hash;
    z3d.g_character_rig.bind_mesh = state.bind_mesh;
    z3d.g_character_rig.deformed_mesh = state.deformed_mesh;
    z3d.g_character_rig.axes = state.axes;
    z3d.g_character_rig.names = state.names;
    z3d.g_character_rig.heatmap = state.heatmap;
    z3d.g_character_rig.selected_bone = state.selected_bone;
    z3d.g_character_rig.joint_editable = state.joint_editable;
    z3d.g_character_rig.bone_count = @intCast(state.bones.len);
    if (!state.joint_editable) z3d.g_character_rig_gizmo = .{};
    z3d.g_character_rig.specimen_separation = state.specimen_separation;

    for (state.bones, 0..) |bone, index| {
        var stored = z3d.CharacterRigGpuBone{
            .parent_index = bone.parent_index,
            .local_pos = bone.local_transform.pos,
            .local_rot = bone.local_transform.rot,
            .local_scale = bone.local_transform.scale,
            .local_tip = bone.local_tip,
            .fit_source = bone.fit_source,
        };
        const name_len = @min(bone.display_name.len, z3d.CHARACTER_RIG_NAME_BYTES);
        @memcpy(stored.name[0..name_len], bone.display_name[0..name_len]);
        stored.name_len = @intCast(name_len);
        z3d.g_character_rig.bones[index] = stored;
        z3d.g_character_rig.bind_global[index] = state.bind_global[index];
        z3d.g_character_rig.pose_global[index] = state.pose_global[index];
        z3d.g_character_rig.skin_matrices[index] = state.skin_matrices[index];
        const palette_at = index * z3d.CHARACTER_RIG_PALETTE_FLOATS;
        @memcpy(z3d.g_character_rig.palette[palette_at .. palette_at + 16], &state.skin_matrices[index]);
        const selected = state.selected_bone != null and state.selected_bone.? == index;
        const color: [4]f32 = if (state.heatmap)
            if (selected) .{ 1.0, 0.18, 0.03, 1.0 } else .{ 0.04, 0.16, 0.72, 1.0 }
        else
            .{ 1.0, 1.0, 1.0, 1.0 };
        @memcpy(z3d.g_character_rig.palette[palette_at + 16 .. palette_at + 20], &color);
    }

    z3d.g_character_rig.selected_vertex_position = null;
    if (state.selected_vertex) |logical_id| {
        if (state.snapshot.render_corner_logical_ids) |logical_ids| {
            for (logical_ids, 0..) |candidate, corner| if (candidate == logical_id) {
                const at = corner * 8;
                z3d.g_character_rig.selected_vertex_position = .{
                    state.snapshot.verts[at],
                    state.snapshot.verts[at + 1],
                    state.snapshot.verts[at + 2],
                };
                break;
            };
        }
    }
    _ = z3d.characterRigBuildSkin(state, z3d.characterRigGeometryFingerprint(state));
}

